Action: run_sql({'query': "WITH parsed_addr AS (\n    SELECT \n        gmap_id,\n        name,\n        address,\n        avg_rating,\n        -- get the street string (usually before the first comma, or second if first is place name)\n        CASE \n            WHEN address LIKE '%,%,%' AND regexp_matches(split_part(address, ',', 1), '^[0-9]+') = false AND regexp_matches(split_part(address, ',', 2), '[0-9]+') = true\n            THEN trim(split_part(address, ',', 2))\n            ELSE trim(split_part(address, ',', 1))\n        END as raw_street_line\n    FROM establishments\n    WHERE address IS NOT NULL AND address != ''\n)\nSELECT \n    address,\n    raw_street_line,\n    -- Strip leading house number\n    regexp_replace(raw_street_line, '^[0-9]+(-[0-9]+)?\\s+(?:[NSEW]\\.?\\s+)?', '') as street_name_no_dir,\n    regexp_replace(raw_street_line, '^[0-9]+(-[0-9]+)?\\s+', '') as street_name_full\nFROM parsed_addr\nLIMIT 25"})

