Action: run_sql({'query': "WITH parsed AS (\n    SELECT \n        gmap_id,\n        name,\n        address,\n        avg_rating,\n        regexp_extract(address, '([0-9]+\\s+(?:[NSEW]\\.?\\s+)?[^,]+)', 1) as raw_street\n    FROM establishments\n    WHERE address IS NOT NULL AND address != ''\n),\ncleaned AS (\n    SELECT \n        *,\n        regexp_replace(\n            regexp_replace(raw_street, '^[0-9]+(-[0-9]+)?\\s+', ''),\n            '\\s+(#|Ste|Suite|Unit| Bldg| Dept| Apt).*', '', 'i'\n        ) as street_full,\n        regexp_replace(\n            regexp_replace(\n                regexp_replace(raw_street, '^[0-9]+(-[0-9]+)?\\s+', ''),\n                '^(N|S|E|W|North|South|East|West)\\.?\\s+', '', 'i'\n            ),\n            '\\s+(#|Ste|Suite|Unit| Bldg| Dept| Apt).*', '', 'i'\n        ) as street_nodir\n    FROM parsed\n    WHERE raw_street != ''\n)\nSELECT \n    '3.0 - 3.9 rating' as rating_group,\n    street_full,\n    COUNT(*) as count\nFROM cleaned\nWHERE avg_rating >= 3.0 AND avg_rating < 4.0\nGROUP BY street_full\nORDER BY count DESC\nLIMIT 15"})

