Action: run_sql({'query': "WITH parsed AS (\n    SELECT \n        gmap_id,\n        name,\n        address,\n        avg_rating,\n        regexp_extract(address, '([0-9]+\\s+(?:[NSEW]\\.?\\s+)?[^,]+)', 1) as raw_street,\n        regexp_extract(address, ',\\s*([^,]+),\\s*UT', 1) as city\n    FROM establishments\n    WHERE address IS NOT NULL AND address != ''\n),\ncleaned AS (\n    SELECT \n        *,\n        regexp_replace(\n            regexp_replace(raw_street, '^[0-9]+(-[0-9]+)?\\s+', ''),\n            '\\s+(#|Ste|Suite|Unit| Bldg| Dept| Apt).*', '', 'i'\n        ) as street_full,\n        regexp_replace(\n            regexp_replace(\n                regexp_replace(raw_street, '^[0-9]+(-[0-9]+)?\\s+', ''),\n                '^(N|S|E|W|North|South|East|West)\\.?\\s+', '', 'i'\n            ),\n            '\\s+(#|Ste|Suite|Unit| Bldg| Dept| Apt).*', '', 'i'\n        ) as street_nodir\n    FROM parsed\n    WHERE raw_street != ''\n)\nSELECT \n    street_full,\n    street_nodir,\n    COUNT(*) as count_3_4_range,\n    COUNT(CASE WHEN ROUND(avg_rating) = 3 THEN 1 END) as count_rounded_3,\n    COUNT(CASE WHEN avg_rating = 3.0 THEN 1 END) as count_exact_3\nFROM cleaned\nWHERE avg_rating >= 3.0 AND avg_rating < 4.0\nGROUP BY street_full, street_nodir\nORDER BY count_3_4_range DESC\nLIMIT 15"})

